def main() -> int:  # noqa: C901
    reg = [{"Rule ID": r[0], "Rule description": r[1], "Source section": r[2], "Chart/example": r[3], "Authority": r[4], "Implementation": r[5]} for r in RULES]
    write_csv(OUT / "rule_authority_registry.csv", reg)
    write_csv(OUT / "source_to_code_traceability.csv", [{"Rule ID": r[0], "Source": f"{DOCX} - {r[2]}", "Code": r[5], "Tests": r[6], "Authority": r[4]} for r in RULES])
    perf = pd.read_csv(OUT / "configuration_performance.csv")
    P = {(r.window, r.config_id): r for r in perf.itertuples()}
    cost = pd.read_csv(OUT / "trade_cost_sensitivity.csv")
    ann = pd.read_csv(OUT / "annual_performance.csv")
    st = json.loads((OUT / "phase60_state_journal.json").read_text())
    ex = json.loads((OUT / "phase60_state_examples.json").read_text())
    rs = json.loads((OUT / "phase60_state_research.json").read_text())
    trades = pd.read_csv(OUT / "all_orb_trades.csv")
    tA = trades[(trades.config_id == "ORB-V2-A")]
    ev = tA["entry_vs_candle_close"].abs()
    a, b = P[("A", "ORB-V2-A")], P[("B", "ORB-V2-A")]
    cA = cost[(cost.window == "A") & (cost.config_id == "ORB-V2-A")]
    c70_1 = cA[(cA.cost_rs_per_trade == 70) & (cA.slippage_points_per_side == 1.0)].iloc[0]
    c70_0 = cA[(cA.cost_rs_per_trade == 70) & (cA.slippage_points_per_side == 0.0)].iloc[0]
    cB = cost[(cost.window == "B") & (cost.config_id == "ORB-V2-A")]
    b70_1 = cB[(cB.cost_rs_per_trade == 70) & (cB.slippage_points_per_side == 1.0)].iloc[0]
    ref = st["reference"]
    cf = st["rule_conformity"]
    pr = [r for r in rs["pattern_route"] if r["window"] == "A"]
    oc = st["outcome_vs_journal_strict_A"]
    mc = st["match_class_counts_by_config"]
    funA = [r for r in rs["funnel"] if r["window"] == "A"]
    lv = {(r["window"], r["config"]): r for r in rs["levels"]}
    gapA = [r for r in rs["gap"] if r["window"] == "A"][0]
    exs = {(e["example_date"], e["feed"]): e for e in ex["summary"]}
    t16 = exs[("2025-09-16", "TV")]
    nB = {c: (P[("A", c)].signals, P[("B", c)].signals) for c in ("ORB-V2-A", "ORB-V2-B", "ORB-V2-C", "ORB-V2-D")}
    old = P[("A", "DIAG-A-OLDSIDE")], P[("B", "DIAG-A-OLDSIDE")]
    ann_rows = ann[(ann.config_id == "ORB-V2-A") & ann.window.isin(["A", "B"])]
    unresolved = [
        ("OD-1", "FEED", "Which data feed is the author's candle: 5paisa or the secondary (TradingView/FYERS-type) feed? The first one-minute print differs (24 Sep 2025: 25,142.55 vs 25,108.75) and the wick, full-body and pin tests, and the gap, depend on it. The rulebook's measured percentages reproduce exactly on the secondary feed only.",
         f"Example 1 passes on the secondary feed (BUY) and fails the pattern rule on 5paisa; primary-window signals {P[('A', 'ORB-V2-A')].signals} (5paisa) vs {P[('A_TV', 'ORB-V2-A')].signals} (secondary)."),
        ("OD-2", "BREAK DEFINITION", "Must the opening candle CROSS a level (open on the old side, close beyond) or is 'close beyond the level' enough, including after a gap? Not stated.", f"signals {nB['ORB-V2-A'][0]} (literal) vs {old[0].signals} (crossing) in the primary window; {nB['ORB-V2-A'][1]} vs {old[1].signals} in 2022-25."),
        ("OD-3", "INNER LEVELS / 'MAJOR'", "How are inner levels found, and is 'major' the previous-day high/low or the prominent late-day zone the author drew (Example 1: the drawn major zone is NOT the day high)?", f"A vs C (cluster zones): signals {nB['ORB-V2-A'][0]} vs {nB['ORB-V2-C'][0]} primary."),
        ("OD-4", "PATTERNS", "Exact hammer / shooting-star proportions and the engulfing reference candle at 09:20.", f"NO_PATTERN is the largest gate: {funA[4]['sessions_remaining']} -> {funA[5]['sessions_remaining']} sessions in the primary window; config D (no engulfing) {nB['ORB-V2-D'][0]} signals."),
        ("OD-5", "WICK RULE vs EXAMPLES", "Example 2 (upper wick 47%) fails the 20% BUY rule; Example 3 (upper wick 66%) passes the SELL rule although the author said it must not be taken. Which is wrong - the rule direction/threshold or the examples?", "see original_examples_reconstruction.md"),
        ("OD-6", "GAP LIMIT", "250 or 300 points?", f"differs on {abs(nB['ORB-V2-B'][1] - nB['ORB-V2-A'][1])} date(s) in 2022-25 and {abs(nB['ORB-V2-B'][0] - nB['ORB-V2-A'][0])} in the primary window (5paisa)."),
        ("OD-7", "ENTRY PRICE", "Rulebook: close of the 9:15 candle. V2 uses the first executable price (open of the 09:20 minute bar). Which is intended (a limit at the close is not guaranteed executable)?", f"|entry - candle close| averages {ev.mean():.2f} points (max {ev.max():.2f}) across V2-A trades."),
        ("OD-8", "END-OF-DAY EXIT", "The rulebook leaves the time open (example 3:15 PM, which is not an executable continuous-session fill); V2 uses the provisional 15:14 bar-open convention.", f"forced exits: {int(a.forced_exits)} (primary), {int(b.forced_exits)} (2022-25) of the V2-A trades."),
        ("OD-9", "SAME-CANDLE STOP/TARGET", "The rulebook speaks of the same 5-minute candle; V2 resolves on one-minute bars (stop first).", "no same-minute collision occurred in the primary run"),
        ("OD-10", "EMA VALUE / CROSS TYPES", "Same-candle EMA value (TO CONFIRM) and whether an intrabar cross and an overnight-gap cross are equivalent.", "labels A/B/C are recorded; nothing is rejected by them"),
        ("OD-11", "ZONE BOUNDARY", "Is a close exactly on the zone edge a break (V2: no, STRICT)?", "configurable; not exercised by the data"),
        ("OD-12", "QUANTITY / COST", "Synthetic quantity (75, the rulebook's example) and the Rs 70 indicative charge are not verified.", "only affects rupee columns"),
        ("OD-13", "JOURNAL EVIDENCE", "The journal records no direction, price or level; the 13 handwritten notes give no level or direction. Exact trade matching is impossible without them.", f"{mc['ORB-V2-A'].get('STRICT_TIMING', 0)} strict-timing matches are date + strategy + time label only."),
        ("OD-15", "GAP REFERENCE CLOSE", "'Previous day close': V2 uses the vendor OFFICIAL daily close (differs from the last 5-minute chart close by a mean 12.7 points, max 88.9, in 2025-26). Using the last chart close flips the 250-point gap decision on 2 primary-window sessions (2026-03-30, 2026-06-12); neither would have signalled.", "no effect on the primary-window signals"),
        ("OD-14", "PORTFOLIO", "ORB V2 is not integrated; priority between a 09:20 ORB and IRF/PDR/PDS/RF is undefined.", "no controller change was made")]
    (OUT / "unresolved_rule_definitions.md").write_text("\n".join([
        "# Unresolved rule definitions and owner decisions", "", "Nothing below was decided by the engine. Each item is either a source gap, a source conflict or a provisional convention. Counts are from the primary 5paisa window unless stated and are shown only to size the impact, never to choose.", "",
        md_table([{"id": u[0], "topic": u[1], "question": u[2], "size of impact": u[3]} for u in unresolved]), "", "## Approvals needed before ORB V2 can replace the old ORB engine", "",
        "1. Decide OD-1 (feed), OD-2 (break), OD-3 (inner levels / major), OD-4 (patterns) and OD-5 (wick rule): together they decide the signals.", "2. Approve or amend the execution conventions OD-7 to OD-9.", "3. Confirm the gap limit (OD-6).",
        "4. Supply direction / level / price for journal ORB dates (or accept date-level evidence only) so exact matching is possible (OD-13).", "5. Decide the portfolio priority and approve any integration (OD-14); then re-run the frozen-baseline regression.", "6. Obtain historical option data before any CE/PE statement is made."]))
    # --------------------------------------------------------------------------------------------------------------- rulebook audit
    (OUT / "latest_rulebook_audit.md").write_text("\n".join([
        "# Audit of the latest rulebook", "", f"* File: `{DOCX}` (SHA-256 `8504fb6fca64a7e168928826970e1735b1aab14d6b2c4c6b3cf567282aac75a7`). The prompt names `Nifty_920_ORB_Rulebook (2).docx`; that file is only in `~/Downloads`, and its bytes are identical to the repository copy `(2) (1).docx` (and to a second Downloads copy), so the repository copy was used. It is untracked in git.",
        "* Read: every paragraph, every table (8 tables incl. the rule matrix), the callout boxes and all 4 embedded images, extracted from the DOCX package at native resolution (`charts_examples/doc_images/`). **Limit:** no DOCX page renderer (LibreOffice) is installed here, so page-layout images could not be produced; the text, tables and images were read from the document XML and the image files.",
        "* Structure: section numbers run 1, 3, 4, ... 10 (there is no section 2; no content appears to be missing). Page headers use '9:15 candle' and '9:20 candle' interchangeably for the first candle.", "",
        "## What it requires (summary)", "", "One decision per day at 09:20 on the NIFTY 50 5-minute chart, only when all of: gap within 250/300 points; 09:20 close on the allowed side of the 200 EMA; at least one previous-day resistance (BUY) / support (SELL), major or inner, broken by the close; green (BUY) / red (SELL) candle "
        "with at least one accepted pattern and a wrong-side wick of at most 20% of the range. Stop 30 / target 60 points, no re-entry, no entry after 09:20.", "",
        "## Every statement the document itself marks as unconfirmed", "", md_table([
            {"where": "4 EMA", "statement": "Compare the 9:20 close with the EMA value on that same candle", "marker": "TO CONFIRM"}, {"where": "5", "statement": "Break = close beyond the level; a wick poke does not count", "marker": "TO CONFIRM"},
            {"where": "5", "statement": "Zone break edges (BUY above top, SELL below bottom)", "marker": "TO CONFIRM"}, {"where": "5", "statement": "How levels are found (swings or hand-drawn)", "marker": "not yet defined"},
            {"where": "6", "statement": "Hammer / shooting-star proportions; engulfing reference at the first candle", "marker": "still to be defined"}, {"where": "6 Ex2", "statement": "Example 2 fails the 20% rule", "marker": "TO CONFIRM"},
            {"where": "6 callout", "statement": "Examples 2 and 3 do not match the written wick rule", "marker": "rule as written applies"}, {"where": "1; 7", "statement": "Maximum gap 250 or 300", "marker": "final value to be confirmed"},
            {"where": "8", "statement": "Entry price = close of the 9:15 candle", "marker": "TO CONFIRM"}, {"where": "8", "statement": "Same-candle stop/target order (conservative default: stop first)", "marker": "TO CONFIRM"},
            {"where": "8", "statement": "End-of-session exit time (e.g. 3:15 PM)", "marker": "to be confirmed"}]), "",
        "## Observations on the document's own numbers", "", "* The EMA values quoted in the examples ('about 25,050 / 25,207 / 25,234') are the TradingView labels at the cursor position in each screenshot (15 Sep 11:45, 17 Sep 13:25, 23 Sep 14:50), not the 09:20 value; the independent EMA reproduces all three labels within 0.25 points.",
        "* The position tools in the screenshots are hand-drawn (Example 1: stop 30.85 / target 60.55 from the entry tag; Example 2: stop 31.55 / target 54.45), so the 'about 25,107 / 25,077 / 25,168' figures are approximate.",
        "* The measured candle percentages (Examples 2 and 3) are reproduced exactly by the secondary feed (see `original_examples_reconstruction.md`).", "", "## Rule registry", "", f"`rule_authority_registry.csv` ({len(RULES)} rules) classifies every rule; `source_to_code_traceability.csv` links each to code and tests."]))
    (OUT / "orb_v2_architecture.md").write_text("\n".join([
        "# ORB V2 architecture", "", "Package `src/nifty_trading/research/orb_v2/` (clean-room; nothing imports the legacy ORB engines, enforced by a test):", "",
        md_table([{"module": m, "role": r} for m, r in [("config.py", "OrbV2Config (every setting + authority label + SHA-256), configs A-D and the diagnostic"), ("models.py", "Level, SessionData, Decision"), ("data_access.py", "window loading (5paisa / secondary), session assembly using the repo loaders, calendar and classify_session"),
                                                          ("opening_candle.py", "five-minute aggregation from raw minutes; the 09:15-09:20 candle (confirmed at 09:20)"), ("ema.py", "EMA(200) recursion"), ("levels.py / zones.py", "previous-day major and inner levels; zone-aware break test"),
                                                          ("patterns.py", "candle metrics and pattern conventions"), ("gap_filter.py", "opening gap"), ("signal_engine.py", "one decision, every failed condition recorded"), ("execution.py", "entry, 30/60, forced exit, ambiguity"),
                                                          ("backtest.py", "runner, metrics, costs"), ("journal.py", "manual-journal reading and classification"), ("audit.py", "SECOND implementation (imports nothing from the engine) used only to audit it"), ("reporting.py", "SVG charts, tables, workbooks")]]), "",
        "Reused verified infrastructure only: processed-parquet loaders, `MarketCalendar`, `classify_session` (usable sessions, official close, closing-auction regime) and `bars_from_frame` (bar executability). All ORB-specific logic is new. "
        "Scripts: `phase60_run.py` (signals, backtest, audit recomputation), `phase60_examples.py`, `phase60_journal.py`, `phase60_charts.py`, `phase60_research.py`, `phase60_workbooks.py`, `phase60_docs.py`, `phase60_snapshot.py` (preservation). Tests: `tests/test_phase60_orb_v2.py`.", "",
        "## Independence evidence", "", "* No import of `strategies.orb*`, `phase53/54/58/59`, the runner or the controller (AST test).", "* `audit.py` re-derives candles (pandas resample), EMA (`ewm`), swings, patterns (cross-multiplied ratios) and the trade (NumPy arrays) and agrees with the engine on every evaluated session of both windows for all five configurations (see `audit_recomputation_summary.json`) and on 2,000 random synthetic sessions; a mutation test proves the comparison can fail."]))
